insert into public.services (slug, name, title, description, hero_image, features, types, tips, questions, sort_order) values ('blouse-stitching', 'Designer Blouse', 'Designer Blouse Stitching', 'Experience the perfect fit with our bespoke blouse stitching service. Whether it is a simple cotton blouse or a heavy bridal design, our master tailors handle every detail with precision. We ensure proper lining, padding, and finishing to give you a boutique look at home.', 'https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&q=80&w=2000', array['Princess Cut & Katori Cut Expertise', 'High-Quality Lining & Piping', 'Sweat Pads & Bra Straps Included', 'Custom Embroidery']::text[], '[{"name":"Princess Cut Blouse","desc":"Designed for a sleek fit, enhancing body contours without seams at the bust point."},{"name":"Katori Cut Blouse","desc":"Traditional style with a specific bust cup cut, ideal for perfect support and fitting."},{"name":"Backless / Deep Neck","desc":"Trendy designs with tassels and dori for a glamorous look."},{"name":"Bridal Embroidery","desc":"Heavy maggam work and zardosi detailing for wedding trousseaus."}]'::jsonb, '[{"title":"Choosing the Right Fabric","desc":"Silk and brocade hold shape well for heavy embroidery, while chiffon needs good lining."},{"title":"Neckline Matters","desc":"Select a neckline that complements your jewelry and face shape."},{"title":"Sleeve Length","desc":"Elbow-length sleeves are trending and add elegance to Kanjeevarams."}]'::jsonb, array['Do you provide lining fabric?', 'Can you replicate a celebrity design?', 'How to measure cup size correctly?', 'What is the turnaround time for bridal blouses?']::text[], 1);
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Simple Blouse', '₹980', 1 from public.services where slug = 'blouse-stitching';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Lining Blouse', '₹1280', 2 from public.services where slug = 'blouse-stitching';
