insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Bridal Maggam Work', '₹3500+', 4 from public.services where slug = 'blouse-stitching';
insert into public.services (slug, name, title, description, hero_image, features, types, tips, questions, sort_order) values ('lehenga-choli', 'Lehenga Choli', 'Best Lehenga Tailor In Chennai', 'HRFashions is best known for its Lehenga stitching service. Our Chennai store has a wide range of perfect lehengas for weddings, parties, and more. We believe that our clients deserve only the best quality of work, and we ensure they receive just that by providing precision stitching with an eye for detail in every single garment we make.
