insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Kali Lehenga', '₹3500', 4 from public.services where slug = 'lehenga-choli';
insert into public.services (slug, name, title, description, hero_image, features, types, tips, questions, sort_order) values ('anarkali', 'Anarkali', 'Royal Anarkali Suits', 'The Anarkali suit allows women to keep a sense of heritage while embracing modern aesthetics. From floor-length gowns to asymmetrical cuts, we craft Anarkalis that make you look regal. Our tailors are experts in handling the volume of fabric and creating the perfect flare (gher) that spins with you.', 'https://images.unsplash.com/photo-1609357605129-26f69add5d6e?auto=format&fit=crop&q=80&w=2000', array['Perfect Flare (Gher) Calculation', 'Kalidar & Umbrella Cuts', 'Heavy Border Attachment', 'Canvas & Can-Can Layering']::text[], '[{"name":"Floor Length Anarkali","desc":"Gown-style suits that add height and elegance, perfect for evening receptions."},{"name":"Angrakha Style","desc":"Overlapping neckline tied with tassels, inspired by Mughal royalty."},{"name":"Cape Style Anarkali","desc":"Modern fusion style with a detached or attached cape, replacing the dupatta."}]'::jsonb, '[{"title":"Fabric Flow","desc":"Georgette and Chiffon are best for a flowy flare, while Silk gives a structured royal look."},{"title":"Length Check","desc":"Always wear your intended heels while measuring for floor-length Anarkalis."}]'::jsonb, array['Can you convert a saree into an Anarkali?', 'Do you add can-can for volume?', 'How much fabric is needed for a full flare?']::text[], 3);
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Basic Anarkali', '₹2200', 1 from public.services where slug = 'anarkali';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Kalidar Anarkali', '₹2800', 2 from public.services where slug = 'anarkali';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Party Wear Gown', '₹3500', 3 from public.services where slug = 'anarkali';
insert into public.service_prices (service_id, label, price_text, sort_order) select id, 'Heavy Bridal Anarkali', '₹5500', 4 from public.services where slug = 'anarkali';
insert into public.services (slug, name, title, description, hero_image, features, types, tips, questions, sort_order) values ('kids-frock', 'Kids Frock', 'Custom Kids Wear', 'Dress your little ones in comfort and style. From birthday frocks to festive lehengas, we stitch soft, skin-friendly garments with playful designs. We ensure extra margin for growth and durable stitching for active kids.', 'https://images.unsplash.com/photo-1518831959646-742c3a14ebf7?auto=format&fit=crop&q=80&w=2000', array['Skin-Friendly Fabrics', 'Comfortable Linings', 'Growth Margins Included', 'Custom Embroidery']::text[], '[{"name":"Party Frocks","desc":"Fluffy net or satin frocks with bows and flower embellishments."},{"name":"Ethnic Lehengas","desc":"Miniature lehengas for festivals, lightweight and easy to carry."},{"name":"Sharara Sets","desc":"Trendy and comfortable sharara sets for little fashionistas."}]'::jsonb, '[{"title":"Comfort First","desc":"Avoid prick, heavy embroidery near the neck and underarms."},{"title":"Size Up","desc":"Kids grow fast; we always leave 2 inches of extra margin inside."}]'::jsonb, array['Do you stitch mother-daughter matching outfits?', 'What fabrics are best for sensitive skin?', 'Do you make costumes for school functions?']::text[], 4);
