insert into public.services (slug, name, title, description, hero_image, features, types, tips, questions, sort_order) values ('kurti', 'Kurti', 'Daily & Office Wear Kurtis', 'Stay comfortable and chic with our custom-stitched Kurtis. Whether for office wear, casual outings, or small gatherings, we offer a variety of cuts and fits. Our tailors ensure the perfect shoulder drop and armhole fit that readymade brands often miss.', 'https://images.unsplash.com/photo-1585487000160-6ebcfceb0d03?auto=format&fit=crop&q=80&w=2000', array['A-Line, Straight & High-Low Cuts', 'Pocket Additions', 'Office-Appropriate Necklines', 'Perfect Shoulder Fitting']::text[], '[{"name":"Straight Cut","desc":"Professional and sleek, pairs perfectly with leggings or trousers."},{"name":"Anarkali Kurti","desc":"Flared and flowy, suitable for semi-casual events."},{"name":"Kaftan Style","desc":"Loose and breezy, perfect for summer comfort."}]'::jsonb, '[{"title":"Choose Cotton","desc":"For daily wear, pure cotton or linen is most breathable."},{"title":"Mix & Match","desc":"Neutral kurtis can be paired with multiple colored dupattas."}]'::jsonb, array['Do you stitch pants with pockets?', 'Can you alter readymade kurtis?', 'What is the price for bulk stitching?']::text[], 5);
