insert into public.services (slug, name, title, description, hero_image, features, types, tips, questions, sort_order) values ('suit-pant', 'Suit Pant', 'Ladies Suit Pant Sets', 'Power dressing meets elegance. Our bespoke ladies pant suits are tailored to give you a sharp, professional silhouette. From formal office wear to chic evening tuxedos, we handle structured tailoring with expertise.', 'https://images.unsplash.com/photo-1594633312681-425c7b97ccd1?auto=format&fit=crop&q=80&w=2000', array['Perfect Trouser Fit', 'Structured Blazers', 'Premium Interlining', 'Comfort Waistbands']::text[], '[{"name":"Formal Office Suit","desc":"Straight cut trousers with a single-breasted blazer."},{"name":"Cigarette Pants","desc":"Slim-fit trousers ending at the ankle, very trendy."},{"name":"Wide Leg Sets","desc":"Comfortable and stylish, perfect for summer formals."}]'::jsonb, '[{"title":"Fabric Choice","desc":"Wool blends or heavy ceremonial fabrics drapes best for suits."},{"title":"Heel Height","desc":"Decide your footwear height before finalizing trouser length."}]'::jsonb, array['Do you stitch blazers for women?', 'How to measure inseam length?', 'Is lining required for white trousers?']::text[], 6);
