insert into public.faqs (service_id, question, answer, sort_order) values (null, 'How do I book?', 'Send a request from the booking page. We confirm the time with you on WhatsApp.', 1);
insert into public.faqs (service_id, question, answer, sort_order) values (null, 'Who do you stitch for?', 'Women and girls. Blouses, lehengas, anarkalis, kurtis, suits and kids’ frocks.', 2);
insert into public.faqs (service_id, question, answer, sort_order) values (null, 'Can I bring my own fabric and design?', 'Yes. Bring your fabric and a photo of the design you like, or choose from ours.', 3);
insert into public.faqs (service_id, question, answer, sort_order) values (null, 'How do I pay?', 'There is no online payment. You pay in person, by UPI or on delivery.', 4);
insert into public.faqs (service_id, question, answer, sort_order) values (null, 'Which areas do you cover?', 'Chennai for now. Message us on WhatsApp to check your area.', 5);
